INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pv-foerderung-2027-eag-novelle-wirtschaftsausschuss-speicherbonus','PV-Förderung 2027: Speicherbonus statt Sekunden-Lotterie','Die EAG-Novelle ist im Wirtschaftsausschuss: Ab 2027 soll der Bund statt PV-Modulen intelligente Speicher fördern, Anträge laufen nach Fertigstellung. Der Beschluss im Dezember braucht eine Zweidrittelmehrheit.','Die **PV-Förderung 2027** in Österreich steht vor dem größten Umbau seit Einführung des Erneuerbaren-Ausbau-Gesetzes (EAG). Am Donnerstag hat der Wirtschaftsausschuss des Nationalrats die Novelle behandelt, mit der die Fördercalls nach dem Prinzip „wer zuerst kommt“ enden und Batteriespeicher in den Mittelpunkt rücken sollen. Damit kann das Paket in der Plenarsitzung im Dezember zur Abstimmung kommen. Ob es dort die nötige Zweidrittelmehrheit bekommt, ist allerdings noch offen.

## Warum die PV-Förderung 2027 neu geregelt wird

Auslöser ist die Bilanz des letzten Fördercalls 2026. Laut Wirtschafts- und Energieministerium wurden 41.322 Anträge mit einem Volumen von rund 192 Millionen Euro eingereicht, zugesagt wurden aber nur 7.007. Bei kleinen Anlagen bis 10 kWp war der Topf nach 29 Sekunden leer, in der Kategorie bis 20 kWp sogar nach 18 Sekunden. Wer nicht in diesem Zeitfenster abgeschickt hatte, ging leer aus. Wir haben über den [letzten Fördercall und den geplanten Speicherbonus](/artikel/pv-foerderung-letzter-foerdercall-2026-speicherbonus-2027) bereits berichtet.

Energie-Staatssekretärin Elisabeth Zehetner (ÖVP) hatte danach erklärt, das bisherige System stoße an seine Grenzen und brauche neue Spielregeln. Die SPÖ spricht in ihrer Aussendung zur Ausschusssitzung von einer „Sekunden-Lotterie“, die beendet werden soll.

## Was das neue Fördermodell vorsieht

Die Eckpunkte, die das Ministerium im November vorgelegt hat und die nun im Parlament liegen, sehen im Kern Folgendes vor:

- **Speicher statt Module:** Die klassische Förderung für PV-Module soll durch einen Speichersystembonus ersetzt werden. Er soll für neue Anlagen ebenso gelten wie für die Nachrüstung bestehender Anlagen.
- **Energiemanagement als Bedingung:** Gefördert werden sollen intelligente Speicher, die über ein Energiemanagementsystem Erzeugung, Speicherung und Verbrauch aufeinander abstimmen und so die Netze entlasten.
- **Laufende Anträge:** Statt fixer Fördercalls sollen Anträge laufend gestellt werden können, und zwar erst nach Fertigstellung bzw. Inbetriebnahme der Anlage.
- **Made in Europe:** Wer Komponenten aus europäischer Produktion einsetzt, soll finanziell bevorzugt werden. Bei neuen Speichern mit neuer PV-Anlage ist laut Ministerium ein europäischer Wechselrichter vorgesehen.
- **Übergang:** Projekte mit intelligentem Speicher, die ab 1. November 2026 in Betrieb gehen, sollen nach derzeitigem Stand 2027 im neuen System einreichen können, wenn sie die Voraussetzungen erfüllen.

Wie hoch der Speicherbonus ausfällt, steht noch nicht fest. Die Details sollen in einer eigenen Verordnung geregelt werden.

## Strompreis: Pauschale und Förderbeitrag 2027 ausgesetzt

Mit derselben Novelle sollen der Erneuerbaren-Förderbeitrag und die Förderpauschale für 2027 ausgesetzt werden. Für einen Haushalt mit 3.500 kWh Jahresverbrauch rechnet das Ministerium mit rund 53 Euro brutto weniger als 2026. Mehr dazu, was die [Aussetzung der Ökostrompauschale für Haushalte](/artikel/oekostrompauschale-2027-ausgesetzt-stromrechnung-haushalte) bedeutet, lesen Sie in unserem Überblick.

Im Ausschuss standen außerdem ein Krisenmechanismus für den Strompreis und ein Industriestrompreis auf der Tagesordnung. Steigt der Netto-Strompreis für Haushalte über 16,5 Cent pro kWh, soll ein Grundbedarf um 10 Cent pro kWh verrechnet werden. Vom Industriestrompreis sollen laut SPÖ rund 400 energieintensive Betriebe profitieren.

## Was PV-Interessenten jetzt beachten sollten

Für EAG-Novelle und Krisenmechanismus braucht die Regierung aus ÖVP, SPÖ und NEOS die Zustimmung mindestens einer Oppositionspartei. Bis zum Beschluss im Nationalrat und zur Verordnung bleibt vieles offen, etwa die Höhe des Bonus und die genauen technischen Kriterien. Wer 2027 eine PV-Anlage plant, sollte daher von Beginn an einen Speicher mit Energiemanagement mitdenken und bei Angeboten auf die Herkunft von Wechselrichter und Speicher achten. Rechnungen und Inbetriebnahme-Unterlagen sollten gut aufbewahrt werden, da die Förderung künftig erst nach Fertigstellung beantragt wird. Die Branchenvertretung PV&B Austria hatte zuletzt die kurze Begutachtungsfrist kritisiert und mehr Klarheit für Betriebe eingefordert.','energie','Photovoltaik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pv-foerderung-2027-eag-novelle-wirtschaftsausschuss-speicherbonus.webp','SPÖ-Parlamentsklub (OTS), APA, BMWET','https://www.ots.at/presseaussendung/OTS_20261126_OTS0171/spoe-schroll-zu-energie-paket-wir-greifen-in-die-preise-ein-und-sorgen-vor','published','2026-11-28T16:55:00.000Z','2026-11-28T16:55:00.000Z','PV-Förderung 2027: Speicherbonus kommt','PV-Förderung 2027: Die EAG-Novelle hat den Wirtschaftsausschuss passiert. Speicherbonus, laufende Anträge, Made in Europe – was jetzt gilt.','PV-Förderung 2027','["PV-Förderung 2027","EAG-Novelle","Speicherbonus","Photovoltaik Förderung Österreich","Stromspeicher Förderung 2027","Speichersystembonus Energiemanagement","PV Fördercall abgeschafft","Erneuerbaren-Förderpauschale 2027"]','PV-Förderung 2027: Batteriespeicher in einer Garage, im Hintergrund ein Hausdach mit Photovoltaik','Photorealistic scene of a modern home battery storage unit mounted on a garage wall in an Austrian single-family house, rooftop solar panels visible through an open garage door, winter afternoon light, alpine foothills in the background, no text, no logos, no readable signs, no people','[{"q":"Gibt es 2027 noch eine Förderung für PV-Module?","a":"Nach den Plänen der Regierung nicht mehr in der bisherigen Form. Gefördert werden sollen intelligente Speicher mit Energiemanagement, bei neuen Anlagen und bei Nachrüstungen."},{"q":"Wann wird die EAG-Novelle beschlossen?","a":"Der Wirtschaftsausschuss hat sie am 26. November behandelt. Die Abstimmung ist für die Plenarsitzung im Dezember geplant, nötig ist eine Zweidrittelmehrheit."},{"q":"Wie hoch ist der Speicherbonus?","a":"Das steht noch nicht fest. Die Details sollen in einer eigenen Verordnung geregelt werden."}]',1) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
